class Cashier {
    int n, discount, orders = 0;
    unordered_map<int, int> price;
public:
    Cashier(int n, int discount, vector<int>& products, vector<int>& prices)
        : n(n), discount(discount) {
        for (int i = 0; i < (int)products.size(); ++i)
            price[products[i]] = prices[i];
    }
    double getBill(vector<int> product, vector<int> amount) {
        double total = 0;
        for (int i = 0; i < (int)product.size(); ++i)
            total += 1.0 * price[product[i]] * amount[i];
        if (++orders % n == 0) total *= (100.0 - discount) / 100.0;
        return total;
    }
};
